import { Injectable, inject, signal, computed, effect, OnDestroy, linkedSignal } from '@angular/core';
import {
    collection, doc, getDoc, setDoc, updateDoc, addDoc,
    query, where, onSnapshot} from 'firebase/firestore';
import { db } from '../../firebase.config';
import { AuthService } from './auth.service';
import { User } from 'firebase/auth';
import {
    PerfilUsuario, Invitacion, Colaborador, CuentaAccesible
} from '../models';

@Injectable({
    providedIn: 'root'
    })
export class AccountService implements OnDestroy {
    private authService = inject(AuthService);
    
    private _misColaboradores = linkedSignal<User | null, Colaborador[]>({
        source: () => this.authService.userSignal(),
        computation: () => []
    });
    private _cuentasAjenas = linkedSignal<User | null, Colaborador[]>({
        source: () => this.authService.userSignal(),
        computation: () => []
    });
    private _invitacionesRecibidas = linkedSignal<User | null, Invitacion[]>({
        source: () => this.authService.userSignal(),
        computation: () => []
    });
    private _invitacionesEnviadas = linkedSignal<User | null, Invitacion[]>({
        source: () => this.authService.userSignal(),
        computation: () => []
    });

    private _unsubColaboradores?: () => void;
    private _unsubAjenas?: () => void;
    private _unsubInvRecibidas?: () => void;
    private _unsubInvEnviadas?: () => void;

    readonly misColaboradores = this._misColaboradores.asReadonly();
    readonly cuentasAjenas = this._cuentasAjenas.asReadonly();
    readonly invitacionesPendientesRecibidas = this._invitacionesRecibidas.asReadonly();
    readonly invitacionesEnviadas = this._invitacionesEnviadas.asReadonly();

    readonly cuentasAccesibles = computed<CuentaAccesible[]>(() => {
        const user = this.authService.userSignal();
        const perfil = this.authService.profileSignal();
        if (!user) return [];

        const propia: CuentaAccesible = {
            propietarioUid: user.uid,
            propietarioNombre: user.displayName ?? user.email ?? 'Mi cuenta',
            propietarioNombreNegocio: perfil?.nombreNegocio ?? 'Mi negocio',
            esPropia: true
        };

        const ajenas: CuentaAccesible[] = this.cuentasAjenas().map(col => ({
            propietarioUid: col.propietarioUid,
            propietarioNombre: col.colaboradorNombre, // nombre del propietario (lo cargamos aparte)
            propietarioNombreNegocio: '',
            esPropia: false
        }));

        return [propia, ...ajenas];
    });

    readonly activeAccountUid = linkedSignal<User | null, string | null>({
        source: () => this.authService.userSignal(),
        computation: (user) => user ? user.uid : null
    });

    readonly effectiveAccountUid = computed(() => {
        return this.activeAccountUid() ?? this.authService.currentUserUid ?? null;
    });

    readonly cuentaActivaInfo = computed<CuentaAccesible | null>(() => {
        const uid = this.effectiveAccountUid();
        if (!uid) return null;
        return this.cuentasAccesibles().find(c => c.propietarioUid === uid) ?? null;
    });

    constructor() {
        effect(() => {
            const user = this.authService.userSignal();
            
            this._unsubColaboradores?.();
            this._unsubAjenas?.();
            this._unsubInvRecibidas?.();
            this._unsubInvEnviadas?.();

            if (!user) {
                return;
            }

            const qMisColab = query(collection(db, 'colaboradores'), where('propietarioUid', '==', user.uid));
            this._unsubColaboradores = onSnapshot(qMisColab, snap => {
                this._misColaboradores.set(snap.docs.map(d => ({ id: d.id, ...d.data() } as Colaborador)));
            });

            const qAjenas = query(collection(db, 'colaboradores'), where('colaboradorUid', '==', user.uid));
            this._unsubAjenas = onSnapshot(qAjenas, snap => {
                this._cuentasAjenas.set(snap.docs.map(d => ({ id: d.id, ...d.data() } as Colaborador)));
            });

            if (user.email) {
                const qInvRec = query(collection(db, 'invitaciones'), where('emailInvitado', '==', user.email), where('estado', '==', 'PENDIENTE'));
                this._unsubInvRecibidas = onSnapshot(qInvRec, snap => {
                    this._invitacionesRecibidas.set(snap.docs.map(d => ({ id: d.id, ...d.data() } as Invitacion)));
                });
            }

            const qInvEnv = query(collection(db, 'invitaciones'), where('propietarioUid', '==', user.uid));
            this._unsubInvEnviadas = onSnapshot(qInvEnv, snap => {
                this._invitacionesEnviadas.set(snap.docs.map(d => ({ id: d.id, ...d.data() } as Invitacion)));
            });
        });

        effect(() => {
            const ajenas = this.cuentasAjenas();
            ajenas.forEach(col => this.cargarPerfilPropietario(col.propietarioUid));
        });
    }

    ngOnDestroy() {
        this._unsubColaboradores?.();
        this._unsubAjenas?.();
        this._unsubInvRecibidas?.();
        this._unsubInvEnviadas?.();
    }

    /** Cambia la cuenta que se está visualizando */
    switchAccount(propietarioUid: string) {
        this.activeAccountUid.set(propietarioUid);
    }

    private _perfilesPropietarios = signal<Map<string, PerfilUsuario>>(new Map());
    readonly perfilesPropietarios = this._perfilesPropietarios.asReadonly();

    private async cargarPerfilPropietario(uid: string) {
        if (this._perfilesPropietarios().has(uid)) return;
        const snap = await getDoc(doc(db, 'usuarios', uid));
        if (snap.exists()) {
            const perfil = snap.data() as PerfilUsuario;
            this._perfilesPropietarios.update(m => {
                const nuevo = new Map(m);
                nuevo.set(uid, perfil);
                return nuevo;
            });
        }
    }

    getNombreNegocioPropietario(uid: string): string {
        return this._perfilesPropietarios().get(uid)?.nombreNegocio
            ?? this._perfilesPropietarios().get(uid)?.nombre
            ?? 'Cuenta ajena';
    }

    getNombrePropietario(uid: string): string {
        return this._perfilesPropietarios().get(uid)?.nombre ?? uid;
    }

    async enviarInvitacion(emailInvitado: string): Promise<void> {
        const user = this.authService.userSignal();
        if (!user) throw new Error('No autenticado');
        const perfil = this.authService.profileSignal();

        // VULN-07 fix: limitar la cantidad de invitaciones pendientes por usuario
        // para evitar spam o abuso de la colección de Firestore.
        const MAX_INVITACIONES_PENDIENTES = 20;
        const pendientes = this.invitacionesEnviadas().filter(inv => inv.estado === 'PENDIENTE');
        if (pendientes.length >= MAX_INVITACIONES_PENDIENTES) {
            throw new Error(`Has alcanzado el límite de ${MAX_INVITACIONES_PENDIENTES} invitaciones pendientes. Cancelá alguna antes de enviar una nueva.`);
        }

        const existing = this.invitacionesEnviadas().find(
            inv => inv.emailInvitado === emailInvitado && inv.estado === 'PENDIENTE'
        );
        if (existing) throw new Error('Ya existe una invitación pendiente para ese email');

        const yaColaborador = this.misColaboradores().find(
            col => col.colaboradorEmail === emailInvitado
        );
        if (yaColaborador) throw new Error('Ese usuario ya es colaborador de tu cuenta');

        if (emailInvitado === user.email) throw new Error('No puedes invitarte a ti mismo');

        const invitacion: Omit<Invitacion, 'id'> = {
            propietarioUid: user.uid,
            propietarioEmail: user.email ?? '',
            propietarioNombre: user.displayName ?? user.email ?? '',
            propietarioNombreNegocio: perfil?.nombreNegocio ?? 'Mi negocio',
            emailInvitado,
            estado: 'PENDIENTE',
            creadoEn: new Date().toISOString()
        };

        await addDoc(collection(db, 'invitaciones'), invitacion);
    }

    async aceptarInvitacion(invitacion: Invitacion): Promise<void> {
        const user = this.authService.userSignal();
        if (!user) throw new Error('No autenticado');

        const colaboradorId = `${invitacion.propietarioUid}_${user.uid}`;

        const colaborador: Omit<Colaborador, 'id'> = {
            propietarioUid: invitacion.propietarioUid,
            colaboradorUid: user.uid,
            colaboradorEmail: user.email ?? '',
            colaboradorNombre: user.displayName ?? user.email ?? '',
            creadoEn: new Date().toISOString(),
            invitacionId: invitacion.id
        };

        await setDoc(doc(db, 'colaboradores', colaboradorId), colaborador);
        await updateDoc(doc(db, 'invitaciones', invitacion.id), { estado: 'ACEPTADA' });
        await this.cargarPerfilPropietario(invitacion.propietarioUid);
    }

    async rechazarInvitacion(invitacion: Invitacion): Promise<void> {
        await updateDoc(doc(db, 'invitaciones', invitacion.id), { estado: 'RECHAZADA' });
    }

    async eliminarColaborador(colaborador: Colaborador): Promise<void> {
        const { deleteDoc, doc: firestoreDoc } = await import('firebase/firestore');
        await deleteDoc(firestoreDoc(db, 'colaboradores', colaborador.id));
    }

    async actualizarNombreNegocio(nombreNegocio: string): Promise<void> {
        const user = this.authService.userSignal();
        if (!user) throw new Error('No autenticado');
        await updateDoc(doc(db, 'usuarios', user.uid), { nombreNegocio });
        const perfilActual = this.authService.profileSignal();
        if (perfilActual) {
            this.authService.profileSignal.set({ ...perfilActual, nombreNegocio });
        }
    }
}

import { Injectable, inject, signal, computed, effect, OnDestroy } from '@angular/core';
import { collection, addDoc, query, where, onSnapshot, doc, deleteDoc, updateDoc } from 'firebase/firestore';
import { AccountService } from './account.service';
import { Articulo } from '../models';
import { db } from '../../firebase.config';

@Injectable({
    providedIn: 'root'
})
export class ArticleService implements OnDestroy {
    private accountService = inject(AccountService);

    private _articulosSignal = signal<Articulo[]>([]);
    private _unsubArticulos?: () => void;

    readonly userArticles = this._articulosSignal.asReadonly();

    readonly totalArticlePurchasePrice = computed(() => {
        return this._articulosSignal().reduce((sum, art) => sum + (art.precioCompra || 0), 0);
    });

    readonly totalArticleSalePrice = computed(() => {
        return this._articulosSignal().reduce((sum, art) => sum + (art.precioVentaContado || 0), 0);
    });

    readonly totalPotentialProfit = computed(() => {
        return this.totalArticleSalePrice() - this.totalArticlePurchasePrice();
    });

    constructor() {
        effect(() => {
            const uid = this.accountService.effectiveAccountUid();
            if (!uid) {
                this._unsubArticulos?.();
                this._articulosSignal.set([]);
                return;
            }
            this._suscribirDatos(uid);
        });
    }

    ngOnDestroy() {
        this._unsubArticulos?.();
    }

    private _suscribirDatos(uid: string) {
        this._unsubArticulos?.();
        const qArts = query(collection(db, 'articulos'), where('usuarioId', '==', uid));
        this._unsubArticulos = onSnapshot(qArts, snap => {
            this._articulosSignal.set(snap.docs.map(d => ({ id: d.id, ...d.data() } as Articulo)));
        });
    }

    private get activeUid(): string {
        const uid = this.accountService.effectiveAccountUid();
        if (!uid) throw new Error('No hay cuenta activa');
        return uid;
    }

    async addArticle(articulo: Omit<Articulo, 'id' | 'usuarioId'>) {
        const uid = this.activeUid;
        const newArticle = { ...articulo, usuarioId: uid };
        return await addDoc(collection(db, 'articulos'), newArticle);
    }

    // VULN-03 fix: solo permite actualizar campos editables.
    // Excluye explícitamente usuarioId para evitar cambio de ownership.
    async updateArticle(id: string, cambios: Pick<Articulo, 'nombre' | 'precioCompra' | 'precioVentaContado'>) {
        const docRef = doc(db, 'articulos', id);
        const { nombre, precioCompra, precioVentaContado } = cambios;
        return await updateDoc(docRef, { nombre, precioCompra, precioVentaContado });
    }

    async deleteArticle(id: string) {
        const docRef = doc(db, 'articulos', id);
        return await deleteDoc(docRef);
    }
}

import { Injectable, inject, signal, OnDestroy } from '@angular/core';
import {
    onAuthStateChanged,
    signOut,
    signInWithPopup,
    signInWithEmailAndPassword,
    createUserWithEmailAndPassword,
    sendEmailVerification,
    reload,
    GoogleAuthProvider,
    User,
    Unsubscribe
} from 'firebase/auth';
import { Router } from '@angular/router';
import { PerfilUsuario } from '../models';
import { auth, db } from '../../firebase.config';
import { AlertController, NavController, ToastController } from '@ionic/angular';
import { doc, getDoc, setDoc, updateDoc } from 'firebase/firestore';

@Injectable({
    providedIn: 'root'
})
export class AuthService implements OnDestroy {
    private router = inject(Router);
    private navCtrl = inject(NavController);
    private alertController = inject(AlertController);
    private toastController = inject(ToastController);
    private _authStateInitialized = signal(false);
    readonly authStateInitialized = this._authStateInitialized.asReadonly();
    // Solo se marca true cuando el check de email_verified terminó de forma segura.
    // Esto evita que login.page navegue al dashboard antes de completar la verificación.
    private _emailCheckReady = signal(false);
    readonly emailCheckReady = this._emailCheckReady.asReadonly();
    private _authUnsubscribe?: Unsubscribe;

    readonly userSignal = signal<User | null>(null);

    constructor() {
        this._authUnsubscribe = onAuthStateChanged(auth, async user => {
            this.userSignal.set(user);
            this._authStateInitialized.set(true);
            // Resetear el flag de check listo hasta completar la verificación
            this._emailCheckReady.set(false);

            if (user) {
                // Recargar el usuario para obtener el estado actualizado del correo
                await reload(user);
                const freshUser = auth.currentUser;

                // Si el usuario usa Email/Contraseña y no verificó su correo, bloquearlo
                if (freshUser && !freshUser.emailVerified && freshUser.providerData[0]?.providerId === 'password') {
                    await this._handleUnverifiedEmail(freshUser);
                    // No marcar emailCheckReady como true: el usuario fue expulsado
                    return;
                }

                // Cargar perfil extendido desde Firestore
                await this._loadOrCreateProfile(user);

                // Check completado: usuario verificado y con perfil cargado
                this._emailCheckReady.set(true);

                // Si estamos en login, navegar al dashboard
                if (this.router.url === '/login' || this.router.url === '/') {
                    this.navCtrl.navigateRoot('/tabs/dashboard', { animated: false });
                }
            } else {
                // Sin usuario: el check está listo (no hay nada que verificar)
                this._emailCheckReady.set(true);
            }
        });
    }

    ngOnDestroy() {
        this._authUnsubscribe?.();
    }

    // Método para esperar a que Firebase nos diga si hay usuario o no
    // y además a que el check de email_verified haya terminado.
    async waitForAuth(): Promise<User | null> {
        if (this._emailCheckReady()) return this.userSignal();
        return new Promise((resolve) => {
            // Esperar al primer evento del onAuthStateChanged de Firebase
            const unsubscribe = onAuthStateChanged(auth, user => {
                unsubscribe();
                // No resolvemos todavía: dejamos que el flujo asíncrono del constructor
                // complete el check de email. Usamos un intervalo corto para polling.
                const interval = setInterval(() => {
                    if (this._emailCheckReady()) {
                        clearInterval(interval);
                        resolve(this.userSignal());
                    }
                }, 50);
            });
        });
    }

    // Signal para datos extendidos del usuario (perfil en Firestore)
    readonly profileSignal = signal<PerfilUsuario | null>(null);

    get currentUserUid(): string | undefined {
        return auth.currentUser?.uid || this.userSignal()?.uid;
    }

    /** Carga o crea el perfil del usuario en Firestore */
    private async _loadOrCreateProfile(user: User): Promise<void> {
        const perfilRef = doc(db, 'usuarios', user.uid);
        const snap = await getDoc(perfilRef);

        if (snap.exists()) {
            const perfil = snap.data() as PerfilUsuario;
            // Actualizar nombre si cambió en Google
            if (perfil.nombre !== user.displayName) {
                await updateDoc(perfilRef, { nombre: user.displayName ?? perfil.nombre });
                perfil.nombre = user.displayName ?? perfil.nombre;
            }
            this.profileSignal.set(perfil);
        } else {
            // Primera vez: crear el perfil
            const nuevoPerfil: PerfilUsuario = {
                uid: user.uid,
                email: user.email ?? '',
                nombre: user.displayName ?? user.email ?? '',
                nombreNegocio: user.displayName ? `Negocio de ${user.displayName.split(' ')[0]}` : 'Mi Negocio',
                creadoEn: new Date().toISOString()
            };
            await setDoc(perfilRef, nuevoPerfil);
            this.profileSignal.set(nuevoPerfil);
        }
    }

    private async _showAuthError(message: string) {
        const toast = await this.toastController.create({
            message,
            duration: 3500,
            position: 'top',
            color: 'danger'
        });
        await toast.present();
    }

    private async _showSuccessToast(message: string) {
        const toast = await this.toastController.create({
            message,
            duration: 5000,
            position: 'top',
            color: 'success'
        });
        await toast.present();
    }

    /**
     * Muestra una alerta al usuario no verificado con la opción de reenviar el
     * correo de verificación. El signOut ocurre DENTRO de los handlers para que
     * el token siga activo al momento de llamar a sendEmailVerification.
     */
    private async _handleUnverifiedEmail(user: User): Promise<void> {
        // Limpiar estado local ANTES de mostrar el alert
        this.userSignal.set(null);
        this.profileSignal.set(null);

        const alert = await this.alertController.create({
            header: 'Verifica tu correo',
            message:
                'Tu cuenta aún no está verificada. Revisá tu bandeja de entrada (y la carpeta de spam) para confirmar tu dirección de correo electrónico.',
            backdropDismiss: false,
            buttons: [
                {
                    text: 'Reenviar correo',
                    handler: () => {
                        // Ejecutamos de forma async pero sin bloquear el cierre del alert
                        (async () => {
                            try {
                                // El usuario aún tiene sesión activa: podemos enviar el correo
                                await sendEmailVerification(user);
                                await this._showSuccessToast('Correo de verificación reenviado. Revisá tu bandeja de entrada.');
                            } catch {
                                await this._showAuthError('No se pudo reenviar el correo. Intentá más tarde.');
                            } finally {
                                // Cerrar sesión después de intentar el reenvío
                                await signOut(auth);
                            }
                        })();
                        return true; // cerrar el alert
                    }
                },
                {
                    text: 'Entendido',
                    role: 'cancel',
                    handler: () => {
                        // Cerrar sesión cuando descarta el alert
                        signOut(auth);
                    }
                }
            ]
        });
        await alert.present();
    }

    private validateEmail(email: string): string | null {
        const normalizedEmail = email.trim().toLowerCase();
        if (!normalizedEmail) {
            return 'Ingresa un correo electrónico.';
        }

        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalizedEmail)) {
            return 'El correo ingresado no es válido.';
        }

        return null;
    }

    async loginWithGoogle() {
        const provider = new GoogleAuthProvider();
        try {
            await signInWithPopup(auth, provider);
        } catch (error: any) {
            await this._showAuthError(
                'No se pudo completar el inicio de sesión. Si estás usando una PWA instalada, asegúrate de que tu navegador permita abrir ventanas emergentes o vuelve a intentarlo.'
            );
            throw error;
        }
    }

    async loginWithEmailAndPassword(email: string, password: string) {
        const emailError = this.validateEmail(email);
        if (emailError) {
            await this._showAuthError(emailError);
            throw new Error(emailError);
        }

        try {
            await signInWithEmailAndPassword(auth, email.trim().toLowerCase(), password);
        } catch (error: any) {
            const message = error?.code === 'auth/invalid-email'
                ? 'El correo ingresado no es válido.'
                : error?.code === 'auth/user-not-found' || error?.code === 'auth/wrong-password'
                    ? 'Correo o contraseña incorrectos.'
                    : 'No se pudo iniciar sesión. Revisa tus datos e inténtalo nuevamente.';
            await this._showAuthError(message);
            throw error;
        }
    }

    async registerWithEmailAndPassword(email: string, password: string) {
        const emailError = this.validateEmail(email);
        if (emailError) {
            await this._showAuthError(emailError);
            throw new Error(emailError);
        }

        if (password.trim().length < 6) {
            await this._showAuthError('La contraseña debe tener al menos 6 caracteres.');
            throw new Error('password-too-short');
        }

        try {
            const credential = await createUserWithEmailAndPassword(auth, email.trim().toLowerCase(), password);
            // Enviar correo de verificación inmediatamente tras el registro
            await sendEmailVerification(credential.user);
            // Cerrar sesión para forzar que el usuario verifique su correo antes de ingresar
            await signOut(auth);
            await this._showSuccessToast(
                '¡Cuenta creada! Te enviamos un correo de verificación. Confirmá tu dirección para poder ingresar.'
            );
        } catch (error: any) {
            const message = error?.code === 'auth/invalid-email'
                ? 'El correo ingresado no es válido.'
                : error?.code === 'auth/email-already-in-use'
                    ? 'Este correo ya está registrado.'
                    : 'No se pudo crear la cuenta. Verificá que el correo sea válido y que la contraseña tenga al menos 6 caracteres.';
            await this._showAuthError(message);
            throw error;
        }
    }

    async logout() {
        try {
            if (this.router.url.includes('login')) return;

            // 1. Limpiar estado local
            this.profileSignal.set(null);

            // 2. Sign out de Firebase Auth (Web/Core)
            await signOut(auth);
            
            // 3. Navegar al login
            await this.router.navigateByUrl('/login', { replaceUrl: true });
            
        } catch (error) {
            console.error('Error durante el cierre de sesión:', error);
            window.location.href = '/login';
        }
    }

    isAuthenticated() {
        return !!auth.currentUser || !!this.userSignal();
    }
}

import { Injectable, inject, signal, effect, OnDestroy } from '@angular/core';
import { collection, addDoc, getDocs, query, where, onSnapshot, doc, deleteDoc, updateDoc } from 'firebase/firestore';
import { AccountService } from './account.service';
import { Cliente } from '../models';
import { db } from '../../firebase.config';

@Injectable({
    providedIn: 'root'
})
export class ClientService implements OnDestroy {
    
    private accountService = inject(AccountService);

    private _clientesSignal = signal<Cliente[]>([]);
    private _unsubClientes?: () => void;

    readonly userClients = this._clientesSignal.asReadonly();

    constructor() {
        effect(() => {
            const uid = this.accountService.effectiveAccountUid();
            if (!uid) {
                this._unsubClientes?.();
                this._clientesSignal.set([]);
                return;
            }
            this._suscribirDatos(uid);
        });
    }

    ngOnDestroy() {
        this._unsubClientes?.();
    }

    private _suscribirDatos(uid: string) {
        this._unsubClientes?.();
        const qClientes = query(collection(db, 'clientes'), where('usuarioId', '==', uid));
        this._unsubClientes = onSnapshot(qClientes, snap => {
            this._clientesSignal.set(snap.docs.map(d => ({ id: d.id, ...d.data() } as Cliente)));
        });
    }

    private get activeUid(): string {
        const uid = this.accountService.effectiveAccountUid();
        if (!uid) throw new Error('No hay cuenta activa');
        return uid;
    }

    async addClient(cliente: Omit<Cliente, 'id' | 'usuarioId' | 'saldoPendiente'>) {
        const uid = this.activeUid;

        try {
            const q = query(
                collection(db, 'clientes'),
                where('usuarioId', '==', uid),
                where('nombre', '==', cliente.nombre),
                where('telefono', '==', cliente.telefono)
            );

            const querySnapshot = await getDocs(q);
            if (!querySnapshot.empty) {
                throw new Error('Ya existe un cliente con este nombre y teléfono');
            }

            const newClient = {
                ...cliente,
                usuarioId: uid,
                saldoPendiente: 0
            };

            const docRef = await addDoc(collection(db, 'clientes'), newClient);
            return docRef;
        } catch (error) {
            throw error;
        }
    }

    // VULN-03 fix: solo permite actualizar campos editables por el usuario.
    // Excluye explícitamente usuarioId y saldoPendiente para evitar manipulación.
    async updateClient(id: string, cambios: Pick<Cliente, 'nombre' | 'telefono'>) {
        const docRef = doc(db, 'clientes', id);
        const { nombre, telefono } = cambios;
        return await updateDoc(docRef, { nombre, telefono });
    }

    async deleteClient(id: string) {
        const docRef = doc(db, 'clientes', id);
        return await deleteDoc(docRef);
    }
}

