import { Component, inject, OnChanges, SimpleChanges, input, output } from '@angular/core';
import { FormBuilder, FormGroup, Validators, ReactiveFormsModule, AbstractControl, ValidationErrors } from '@angular/forms';
import { IonHeader, IonToolbar, IonTitle, IonContent, IonItem, IonLabel, IonInput, IonButton, IonModal, IonNote } from '@ionic/angular/standalone';
import { Cliente } from '../../../../core/models';

type ClienteFormData = Pick<Cliente, 'nombre' | 'telefono'>;

function maxWordsValidator(maxWords: number) {
  return (control: AbstractControl): ValidationErrors | null => {
    if (!control.value) return null;
    const words = control.value.trim().split(/\s+/);
    return words.length > maxWords ? { maxWords: true } : null;
  };
}

@Component({
  selector: 'app-client-modal',
  templateUrl: './client-modal.component.html',
  standalone: true,
  imports: [IonHeader, IonToolbar, IonTitle, IonContent, IonItem, IonLabel, IonInput, IonButton, IonModal, IonNote, ReactiveFormsModule]
})
export class ClientModalComponent implements OnChanges {
  readonly isOpen = input(false);
  readonly isSaving = input(false);
  readonly isEditing = input(false);
  readonly clientData = input<Cliente | null>(null);
  readonly didDismiss = output<void>();
  readonly save = output<ClienteFormData>();

  private fb = inject(FormBuilder);

  clientForm = this.fb.nonNullable.group({
    nombre: ['', [
      Validators.required, 
      Validators.minLength(3),
      Validators.maxLength(40),
      Validators.pattern(/^[a-zA-ZáéíóúÁÉÍÓÚñÑ\s]+$/),
      maxWordsValidator(2)
    ]],
    telefono: ['', [
      Validators.required,
      Validators.minLength(8),
      Validators.maxLength(15),
      Validators.pattern(/^\+?[\d\s\-]+$/)
    ]]
  });

  ngOnChanges(changes: SimpleChanges) {
    if (changes['isOpen'] && changes['isOpen'].currentValue) {
      if (this.isEditing() && this.clientData()) {
        this.clientForm.patchValue({
          nombre: this.clientData()!.nombre,
          telefono: this.clientData()!.telefono
        });
      } else {
        this.clientForm.reset();
      }
    }
  }

  onSubmit() {
    if (this.clientForm.valid && !this.isSaving()) {
      const formData = this.clientForm.getRawValue() as ClienteFormData;
      this.save.emit(formData);
    }
  }
}

import { Component, inject, ChangeDetectorRef, ChangeDetectionStrategy } from '@angular/core';
import {
  IonHeader, IonToolbar, IonTitle, IonContent,
  IonIcon, IonFab, IonFabButton } from '@ionic/angular/standalone';
import { ClientService } from '../../core/services/client.service';
import { UiService } from '../../core/services/ui.service';
import { addIcons } from 'ionicons';
import { logoWhatsapp, addOutline, personAddOutline, trashOutline, createOutline } from 'ionicons/icons';
import { ClientListComponent } from './components/client-list/client-list.component';
import { ClientModalComponent } from './components/client-modal/client-modal.component';
import { Cliente } from '../../core/models';
import { NotificationBellComponent } from '../../shared/components/notification-bell/notification-bell.component';

@Component({
  selector: 'app-clients',
  templateUrl: 'clients.page.html',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    IonFabButton, IonHeader, IonToolbar, IonTitle, IonContent,
    IonIcon, IonFab, ClientListComponent, ClientModalComponent, NotificationBellComponent
  ],
})
export class ClientsPage {
  public clientService = inject(ClientService);
  private cdr = inject(ChangeDetectorRef);
  private uiService = inject(UiService);

  isModalOpen = false;
  isSaving = false;
  editingClientId: string | null = null;
  editingClientData: Cliente | null = null;

  constructor() {
    addIcons({ addOutline, personAddOutline, logoWhatsapp, trashOutline, createOutline });
  }

  openWhatsApp(phone: string) {
    const cleanPhone = phone.replace(/[^\d+]/g, '');
    window.open(`https://wa.me/${cleanPhone}`, '_blank');
  }

  openAddModal() {
    this.editingClientId = null;
    this.editingClientData = null;
    this.isModalOpen = true;
  }

  editClient(client: Cliente) {
    this.editingClientId = client.id || null;
    this.editingClientData = client;
    this.isModalOpen = true;
  }

  closeModal() {
    this.isModalOpen = false;
    this.editingClientId = null;
    this.editingClientData = null;
  }

  async deleteClient(id: string) {
    await this.uiService.showConfirmAlert({
      header: 'Confirmar eliminación',
      message: '¿Estás seguro de que deseas eliminar este cliente?',
      confirmText: 'Eliminar',
      confirmRole: 'destructive',
      onConfirm: async () => {
        try {
          await this.clientService.deleteClient(id);
        } catch (error) {
          console.error('Error deleting client:', error);
          await this.uiService.showErrorAlert('No se pudo eliminar el cliente', error);
        }
      }
    });
  }

  async onSubmit(formData: Pick<Cliente, 'nombre' | 'telefono'>) {
    if (!this.isSaving) {
      this.isSaving = true;
      this.cdr.detectChanges();
      try {
        if (this.editingClientId) {
          await this.clientService.updateClient(this.editingClientId, formData);
        } else {
          await this.clientService.addClient(formData as any);
        }
        this.closeModal();
        this.cdr.detectChanges();
      } catch (error: any) {
        await this.uiService.showErrorAlert('Error al guardar el cliente', error);
      } finally {
        this.isSaving = false;
        this.cdr.detectChanges();
      }
    }
  }
}

