import { Component, ChangeDetectionStrategy, OnChanges, SimpleChanges, inject, input, output } from '@angular/core';
import { CommonModule, DecimalPipe } from '@angular/common';
import { FormBuilder, FormGroup, Validators, ReactiveFormsModule } from '@angular/forms';
import {
  IonModal, IonHeader, IonToolbar, IonTitle, IonButtons, IonButton,
  IonContent, IonItem, IonLabel, IonInput, IonSelect, IonSelectOption, IonCheckbox,
  IonDatetime, IonDatetimeButton, IonList, IonText
} from '@ionic/angular/standalone';
import { ClientService } from '../../../../core/services/client.service';
import { ArticleService } from '../../../../core/services/article.service';
import { LoanPlanService } from '../../../../core/services/loan-plan.service';
import { OperationService } from '../../../../core/services/operation.service';

export interface OperationFormData {
  tipo: 'VENTA' | 'PRESTAMO';
  montoBase: number;
  porcentajeRecargo: number;
  clienteId: string;
  articuloId?: string;
  prestamoId?: string;
  cuotasCount: number;
  tieneVencimiento: boolean;
  periodicidad?: 'SEMANAL' | 'QUINCENAL' | 'MENSUAL';
  diaSemana?: number;
  diaVencimiento?: number;
  fechaPrimerVencimiento?: string;
}

@Component({
  selector: 'app-operation-modal',
  templateUrl: './operation-modal.component.html',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    CommonModule, ReactiveFormsModule, DecimalPipe,
    IonModal, IonHeader, IonToolbar, IonTitle, IonButtons, IonButton,
    IonContent, IonItem, IonLabel, IonInput, IonSelect, IonSelectOption, IonCheckbox,
    IonDatetime, IonDatetimeButton, IonList, IonText
  ]
})
export class OperationModalComponent implements OnChanges {
  public clientService = inject(ClientService);
  public articleService = inject(ArticleService);
  public loanPlanService = inject(LoanPlanService);
  public operationService = inject(OperationService);
  private fb = inject(FormBuilder);

  readonly isOpen = input(false);
  readonly isSaving = input(false);
  readonly operationIdToEdit = input<string | null>(null);
  readonly initialData = input<Partial<OperationFormData> | null>(null);

  readonly dismiss = output<void>();
  readonly save = output<OperationFormData>();

  opForm = this.fb.nonNullable.group({
    tipo: ['VENTA' as 'VENTA' | 'PRESTAMO', Validators.required],
    montoBase: [0, [Validators.required, Validators.min(1)]],
    porcentajeRecargo: [0, [Validators.required, Validators.min(0)]],
    clienteId: ['', Validators.required],
    articuloId: [''],
    prestamoId: [''],
    cuotasCount: [1, [Validators.required, Validators.min(1)]],
    tieneVencimiento: [false],
    periodicidad: ['MENSUAL' as 'SEMANAL' | 'QUINCENAL' | 'MENSUAL'],
    diaSemana: [new Date().getDay()],
    diaVencimiento: [5, [Validators.min(1), Validators.max(31)]],
    fechaPrimerVencimiento: [new Date().toISOString()]
  });

  ngOnChanges(changes: SimpleChanges) {
    if (changes['initialData'] && this.initialData()) {
      this.opForm.patchValue(this.initialData()!);
    } else if (changes['isOpen'] && this.isOpen() && !this.operationIdToEdit()) {
      this.opForm.reset({
        tipo: 'VENTA',
        montoBase: 0,
        porcentajeRecargo: 0,
        articuloId: '',
        prestamoId: '',
        cuotasCount: 1,
        tieneVencimiento: false,
        periodicidad: 'MENSUAL',
        diaSemana: new Date().getDay(),
        diaVencimiento: 5,
        fechaPrimerVencimiento: new Date().toISOString()
      });
    }
  }

  onArticleChange(event: any) {
    const articleId = event.detail.value;
    if (articleId) {
      const article = this.articleService.userArticles().find(a => a.id === articleId);
      if (article) {
        this.opForm.patchValue({ montoBase: article.precioVentaContado });
      }
    }
  }

  onLoanChange(event: any) {
    const planId = event.detail.value;
    if (planId) {
      const plan = this.loanPlanService.userLoanPlans().find(p => p.id === planId);
      if (plan) {
        this.opForm.patchValue({
          montoBase: plan.montoBase,
          porcentajeRecargo: plan.porcentajeRecargo,
          cuotasCount: plan.cuotasCount,
          tieneVencimiento: true,
          periodicidad: plan.periodicidad,
          diaSemana: plan.diaSemana ?? new Date().getDay(),
          diaVencimiento: plan.diaVencimiento ?? 5
        });
      }
    }
  }

  calculatePreview() {
    const { montoBase, porcentajeRecargo } = this.opForm.getRawValue();
    return this.operationService.calculateTotal(montoBase, porcentajeRecargo);
  }

  onSubmit() {
    if (this.opForm.valid && !this.isSaving()) {
      this.save.emit(this.opForm.getRawValue());
    }
  }
}

import { Component, ChangeDetectionStrategy, inject, input, output } from '@angular/core';
import { CommonModule, DecimalPipe, DatePipe } from '@angular/common';
import {
  IonList, IonItem, IonLabel, IonButton, IonIcon, IonNote, IonBadge,
  IonAccordion, IonAccordionGroup, IonItemDivider, IonText
} from '@ionic/angular/standalone';
import { Operacion } from '../../../../core/models';
import { ClientService } from '../../../../core/services/client.service';
import { OperationService } from '../../../../core/services/operation.service';

@Component({
  selector: 'app-operations-list',
  templateUrl: './operations-list.component.html',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    CommonModule, DecimalPipe, DatePipe,
    IonList, IonItem, IonLabel, IonButton, IonIcon, IonNote, IonBadge,
    IonAccordion, IonAccordionGroup, IonItemDivider, IonText
  ]
})
export class OperationsListComponent {
  public clientService = inject(ClientService);
  public operationService = inject(OperationService);

  readonly operations = input<Operacion[]>([]);
  readonly edit = output<string>();
  readonly delete = output<string>();
  readonly pay = output<string>();

  getClientName(id: string) {
    const client = this.clientService.userClients().find(c => c.id === id);
    return client ? client.nombre : 'Cliente Desconocido';
  }

  getPorcentajeRecargo(op: Operacion): number {
    if (op.tipo === 'VENTA' && op.ventaId) {
      const venta = this.operationService.userSales().find(v => v.id === op.ventaId);
      return venta ? venta.porcentajeRecargo : 0;
    } else if (op.tipo === 'PRESTAMO' && op.prestamoId) {
      const prestamo = this.operationService.userLoans().find(p => p.id === op.prestamoId);
      return prestamo ? prestamo.porcentajeRecargo : 0;
    }
    return 0;
  }

  getTotalFinal(op: Operacion): number {
    if (op.tipo === 'VENTA' && op.ventaId) {
      const venta = this.operationService.userSales().find(v => v.id === op.ventaId);
      return venta ? venta.totalFinal : 0;
    } else if (op.tipo === 'PRESTAMO' && op.prestamoId) {
      const prestamo = this.operationService.userLoans().find(p => p.id === op.prestamoId);
      return prestamo ? prestamo.totalFinal : 0;
    }
    return 0;
  }

  getInstalments(opId: string) {
    return this.operationService.userInstalments()
      .filter(i => i.operacionId === opId)
      .sort((a, b) => {
        if (!a.vencimiento) return 1;
        if (!b.vencimiento) return -1;
        return new Date(a.vencimiento).getTime() - new Date(b.vencimiento).getTime();
      });
  }

  getStatusColor(estado: string) {
    switch (estado) {
      case 'PAGADA': return 'success';
      case 'PENDIENTE': return 'warning';
      case 'VENCIDA': return 'danger';
      default: return 'medium';
    }
  }
}

import { Component, inject, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import {
  IonFab, IonFabButton, IonIcon
} from '@ionic/angular/standalone';
import { OperationService } from '../../../core/services/operation.service';
import { UiService } from '../../../core/services/ui.service';
import { addIcons } from 'ionicons';
import {
  trashOutline, cashOutline, receiptOutline, createOutline,
  calendarOutline, personOutline, addOutline
} from 'ionicons/icons';
import { OperationsListComponent } from './operations-list/operations-list.component';
import { OperationModalComponent, OperationFormData } from './operation-modal/operation-modal.component';

@Component({
  selector: 'app-operations-tab',
  templateUrl: 'operations-tab.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    CommonModule,
    IonFab, IonFabButton, IonIcon,
    OperationsListComponent, OperationModalComponent
  ],
})
export class OperationsTabComponent {
  public operationService = inject(OperationService);
  private uiService = inject(UiService);
  private cdr = inject(ChangeDetectorRef);

  isModalOpen = false;
  isSavingOp = false;
  operationIdToEdit: string | null = null;
  initialOperationData: any = null;

  constructor() {
    addIcons({
      trashOutline, cashOutline, receiptOutline, createOutline,
      calendarOutline, personOutline, addOutline
    });
  }

  openAddModal() {
    this.operationIdToEdit = null;
    this.initialOperationData = null;
    this.isModalOpen = true;
  }

  openEditModal(id: string) {
    this.operationIdToEdit = id;
    this.loadOperation(id);
    this.isModalOpen = true;
  }

  closeModal() {
    this.isModalOpen = false;
    this.operationIdToEdit = null;
    this.initialOperationData = null;
  }

  private loadOperation(id: string) {
    const op = this.operationService.userOperations().find(o => o.id === id);
    if (op) {
      let montoBase = 0;
      let porcentajeRecargo = 0;
      let articuloId = '';
      let planPrestamoId = '';

      if (op.tipo === 'VENTA' && op.ventaId) {
        const venta = this.operationService.userSales().find(v => v.id === op.ventaId);
        if (venta) {
          montoBase = venta.montoBase;
          porcentajeRecargo = venta.porcentajeRecargo;
          articuloId = venta.articuloId || '';
        }
      } else if (op.tipo === 'PRESTAMO' && op.prestamoId) {
        const prestamo = this.operationService.userLoans().find(p => p.id === op.prestamoId);
        if (prestamo) {
          montoBase = prestamo.montoBase;
          porcentajeRecargo = prestamo.porcentajeRecargo;
          planPrestamoId = prestamo.planId || '';
        }
      }

      this.initialOperationData = {
        tipo: op.tipo,
        montoBase,
        porcentajeRecargo,
        clienteId: op.clienteId,
        articuloId,
        prestamoId: planPrestamoId,
        cuotasCount: op.cuotasCount,
        tieneVencimiento: !!op.fechaPrimerVencimiento,
        periodicidad: op.periodicidad || 'MENSUAL',
        diaSemana: op.diaSemana ?? new Date().getDay(),
        diaVencimiento: op.diaVencimiento ?? 5,
        fechaPrimerVencimiento: op.fechaPrimerVencimiento || new Date().toISOString()
      };
    }
  }

  async onSubmitOperation(opFormData: OperationFormData) {
    if (!this.isSavingOp) {
      this.isSavingOp = true;
      this.cdr.detectChanges();

      try {
        const opData = {
          ...opFormData,
          montoBase: Number(opFormData.montoBase),
          porcentajeRecargo: Number(opFormData.porcentajeRecargo),
          cuotasCount: Number(opFormData.cuotasCount)
        };

        if (this.operationIdToEdit) {
          await this.operationService.updateOperation(this.operationIdToEdit, opData as any);
        } else {
          await this.operationService.addOperation(opData as any);
        }

        await this.uiService.showConfirmAlert({
          header: 'Éxito',
          message: this.operationIdToEdit ? 'Operación actualizada con éxito' : 'Operación guardada con éxito',
          confirmText: 'OK',
          cancelText: 'Cerrar',
          onConfirm: () => {
            this.closeModal();
          }
        });
      } catch (error) {
        await this.uiService.showErrorAlert('Error al guardar la operación', error);
      } finally {
        this.isSavingOp = false;
        this.cdr.detectChanges();
      }
    }
  }

  async payInstallment(cuotaId: string) {
    try {
      await this.operationService.payInstallment(cuotaId);
    } catch (error) {
      await this.uiService.showErrorAlert('No se pudo registrar el pago', error);
    }
  }

  async deleteOperation(id: string) {
    await this.uiService.showConfirmAlert({
      header: 'Confirmar eliminación',
      message: '¿Estás seguro de que deseas eliminar esta operación? Se eliminarán también todas sus cuotas asociadas.',
      confirmText: 'Eliminar',
      confirmRole: 'destructive',
      onConfirm: async () => {
        try {
          await this.operationService.deleteOperation(id);
        } catch (error) {
          await this.uiService.showErrorAlert('No se pudo eliminar la operación', error);
        }
      }
    });
  }
}

